FractionalResampler::FractionalResampler()
    : m_histWrite(0), m_phaseAccum(0.0f) {
    std::memset(m_history, 0, sizeof(m_history));
}

uint32_t FractionalResampler::process(const float* in, uint32_t nIn,
                                      float* out, uint32_t nOut, float ratio) {
    for (uint32_t i = 0; i < nIn; ++i) {
        m_history[m_histWrite] = in[i];
        m_histWrite = (m_histWrite + 1) % FR_HISTORY_SIZE;
    }

    uint32_t outIdx = 0;
    while (outIdx < nOut) {
        uint32_t phaseIdx = static_cast<uint32_t>(m_phaseAccum) % FR_RESAMPLER_PHASES;
        const float* c = kCoeffs[phaseIdx];

        uint32_t readPos = (m_histWrite + FR_HISTORY_SIZE - FR_RESAMPLER_TAPS) % FR_HISTORY_SIZE;
        float sum = 0.0f;
        for (uint32_t t = 0; t < FR_RESAMPLER_TAPS; ++t) {
            sum += m_history[readPos] * c[t];
            readPos = (readPos + 1) % FR_HISTORY_SIZE;
        }

        out[outIdx++] = sum;
        m_phaseAccum += ratio * static_cast<float>(FR_RESAMPLER_PHASES);
    }

    return outIdx;
}

void FractionalResampler::reset() {
    std::memset(m_history, 0, sizeof(m_history));
    m_histWrite = 0;
    m_phaseAccum = 0.0f;
}
